package com.swen3.dms.storage;

import java.io.InputStream;
import org.springframework.core.io.Resource;

/** Stores file contents under opaque keys generated by the storage. */
public interface DocumentStorage {

    /** Stores the stream's content and returns the key to retrieve it with. */
    String store(InputStream content);

    Resource load(String key);

    /** Deletes the content stored under the key; does nothing if there is none. */
    void delete(String key);
}
